'use strict';

/**
* Round a single-precision floating-point number to the nearest multiple of `10^n`.
*
* @module @stdlib/math/base/special/round10f
*
* @example
* var round10f = require( '@stdlib/math/base/special/round10f' );
*
* var v = round10f( 3.1415926, 0 );
* // returns 1
*
* v = round10f( 3.1415926, -1 );
* // returns 1
*
* v = round10f( 123.45, 1 );
* // returns 100
*
* v = round10f( -2.5, 0 );
* // returns -1
*/

// MODULES //

var round10f = require( './main.js' );


// EXPORTS //

module.exports = round10f;
